    expect(es.get("model")).toBe("flux-general-multi");
    expect(es.getAll("language_hint")).toEqual(["es"]);
  });

  it("only accepts a language's own voices", () => {
    expect(normalizeVoice("valentina", "es")).toBe("flux-valentina-es");
