:focus-visible { outline-color: var(--lamp-strong); }

/* the illustrations */
/* The canvas never takes part in layout: CSS alone sizes the box, and the
   sketch fits itself to it. Otherwise the canvas widens its grid column, the
   resize observer sees a bigger box, and the scene grows without end. */
.scene-art { position: relative; width: 100%; height: 100%; min-width: 0; background: linear-gradient(#0b1030, #222a5e); overflow: hidden; contain: strict; }
.scene-art canvas { position: absolute; inset: 0; display: block; max-width: 100%; max-height: 100%; }
.hero-art, .hero-copy, .reader-grid > *, .story-card { min-width: 0; }
.hero-book .scene-art { aspect-ratio: 600 / 440; height: auto; }
.picture-panel .scene-art { position: absolute; inset: 0; }
.cover .scene-art { transition: transform .5s; }
.story-card:hover .cover .scene-art { transform: scale(1.04); }

/* nav */
.nav { border-bottom-color: var(--line); }
.brand { font-weight: 600; letter-spacing: -1px; }
.brand-mark, .brand-dot { color: var(--lamp); }
.nav nav { font-size: 14px; }
.nav nav a.active { color: var(--lamp-strong); box-shadow: 0 2px var(--lamp); }
.nav nav .nav-create { background: rgba(242, 189, 87, .12); color: var(--lamp-strong); border: 1px solid rgba(242, 189, 87, .3); }

/* type that was too small to read */
.eyebrow { font-size: 12px; color: var(--lamp); letter-spacing: 2.2px; }
.eyebrow > span { background: var(--lamp); }
.hero-description { font-size: 17px; color: var(--muted); }
.hero-note { font-size: 13px; color: var(--faint); }
.how-strip strong { font-size: 15px; }
.how-strip p > span { font-size: 13px; color: var(--muted); }
.card-meta { font-size: 12px; color: var(--faint); }
.card-text p { font-size: 14px; color: var(--muted); min-height: 0; }
.card-action { font-size: 13px; color: var(--lamp-strong); border-top-color: var(--line); margin-top: auto; }
.cover-badge { font-size: 12px; background: rgba(13, 17, 42, .72); color: var(--ink); backdrop-filter: blur(6px); }
.cover-arrow { background: rgba(243, 234, 216, .92); color: #1b1d36; }
.filters button { font-size: 14px; border-color: var(--line); color: var(--ink); }
.filters button.selected { background: var(--lamp); color: var(--on-lamp); border-color: var(--lamp); }
.small { font-size: 14px; }
.create-banner p { font-size: 14px; color: var(--muted); }
footer { color: var(--faint); }
footer p, footer > span { font-size: 13px; }
footer .brand { color: var(--lamp); }
.button { font-size: 15px; }

/* buttons */
.primary { background: var(--lamp); color: var(--on-lamp); font-weight: 700; }
.primary:hover { background: var(--lamp-strong); }
.secondary { border-color: rgba(243, 234, 216, .22); color: var(--ink); }
.secondary:hover:not(:disabled) { background: rgba(243, 234, 216, .06); }
.light { background: var(--lamp); color: var(--on-lamp); font-weight: 700; }

/* hero */
.hero-book { background: var(--night-2); border: 6px solid #2a335f; box-shadow: 10px 14px 0 #0a0e24, 0 30px 90px rgba(242, 189, 87, .10); }
.book-label { background: var(--night-2); }
.book-label span { color: var(--lamp); font-size: 11px; }
.book-label strong { color: var(--ink); }
.orbit-star { color: var(--lamp); }
/* tucked into the empty sky at the top-left, clear of the characters and the book label */
.speech-note { top: 34px; bottom: auto; left: -34px; max-width: 176px; padding: 10px 14px; font-size: 14px; line-height: 1.35; transform: rotate(-3deg); border-radius: 14px 14px 14px 2px; background: #f6ecd7; color: #23203d; border-color: #e9dcbf; box-shadow: 0 10px 30px rgba(0, 0, 0, .35); }
@media (max-width: 700px) { .speech-note { top: 10px; left: -14px; max-width: 150px; font-size: 13px; } }
.how-strip, .how-strip > div { border-color: var(--line); }
.step-icon { border-color: rgba(242, 189, 87, .4); color: var(--lamp-strong); }

/* cards */
.story-card { display: flex; flex-direction: column; background: var(--night-1); border-color: var(--line); }
.story-card:hover { box-shadow: 0 16px 40px rgba(0, 0, 0, .45), 0 0 0 1px rgba(242, 189, 87, .25); }
.cover { background: #0b1030; }
.card-text { flex: 1; display: flex; flex-direction: column; }
.card-text h3 { min-height: 0; }
.create-banner { background: var(--night-2); border: 1px solid var(--line); }
.banner-star { color: var(--lamp); }

/* reader */
.reader-grid { background: var(--night-1); border-color: var(--line); }
.picture-panel { background: #0b1030; }
.picture-caption { background: rgba(13, 17, 42, .74); color: var(--ink); font-size: 13px; backdrop-filter: blur(8px); }
.mode-switch { background: var(--night-3); border-color: var(--line); }
.mode-switch button { font-size: 14px; }
.mode-switch button[aria-pressed=true] { background: var(--lamp); color: var(--on-lamp); font-weight: 700; }
.how-strip strong { font-weight:500; font-size:12px; }
.how-strip p>span { display:block; font-size:10px; color:#7f8276; margin-top:6px; }
.stories-section { padding-top:53px; scroll-margin-top:25px; }
.section-heading { display:flex; justify-content:space-between; align-items:end; }
.section-heading .eyebrow { margin-bottom:12px; }
.small { font-size:12px; line-height:1.7; }
.muted { color:var(--muted); line-height:1.7; }
.filters { display:flex; gap:9px; margin:25px 0; flex-wrap:wrap; }
.filters button { background:transparent; border:1px solid #dfe1d4; border-radius:30px; padding:9px 19px; font-size:11px; min-height:36px; }
.filters button.selected { background:var(--green); color:#fff; border-color:var(--green); }
.story-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:22px; }
.story-card { border:1px solid #e1e3d6; border-radius:11px; overflow:hidden; background:#fdfcf8; transition:transform .22s,box-shadow .22s; display:block; }
.story-card:hover { transform:translateY(-5px); box-shadow:0 10px 25px #263c3210; }
.cover { position:relative; height:215px; overflow:hidden; background:#e5e6d4; }
.cover svg,.cover .scene-image { width:100%; height:100%; object-fit:cover; display:block; }
.cover svg { transform:scale(1.09); transition:transform .4s; }
.story-card:hover .cover svg { transform:scale(1.15); }
.cover-badge { position:absolute; top:13px; left:13px; font-size:8px; background:#fffcf0de; border-radius:20px; padding:6px 10px; color:#4c5e49; }
.cover-arrow { position:absolute; right:12px; bottom:12px; background:#fff9eb; border-radius:50%; height:28px; width:28px; display:grid; place-items:center; }
.card-text { padding:19px 18px 18px; }
.card-meta { font-size:9px; color:#828779; display:block; margin-bottom:10px; }
.card-text h3 { min-height:54px; }
.card-text p { font-size:11px; line-height:1.7; color:#7a7e72; margin-top:10px; min-height:57px; }
.card-action { display:flex; justify-content:space-between; border-top:1px solid #e8e9df; margin-top:18px; padding-top:13px; font-size:10px; font-weight:600; }
